import 'package:flutter/material.dart';import 'package:flutter_test/flutter_test.dart';import 'package:fluxidi_tracking/driver/driver_ride_offer.dart';import 'package:fluxidi_tracking/driver/driver_ride_offer_panel.dart';
void main(){testWidgets('P22 driver sees ordered stops and return, preserves countdown and decline',(tester)async{final row=<String,dynamic>{'offer_id':'o','vehicle_id':'v','version':1,'human_acceptance_required':true,'ack_deadline_ms':30000,'currency':'EUR','pickup_address':'Pickup','dropoff_address':'Destination','stops':['First stop','Second stop'],'return_info':{'enabled':true,'pickup_time':'18:00','pickup':'Destination','destination':'Pickup'},'requirements':{'passengers':4,'luggage':2,'capabilities':['wheelchair']}};final offer=DriverRideOffer.parse(row,'v');String? action;await tester.pumpWidget(MaterialApp(home:DriverRideOfferPanel(offer:offer,nowMs:1000,onDecision:(a)=>action=a)));await tester.pumpAndSettle();expect(find.text('Tussenstop: First stop'),findsOneWidget);expect(find.text('Tussenstop: Second stop'),findsOneWidget);expect(find.textContaining('Retour: 18:00'),findsOneWidget);expect(find.textContaining('wheelchair'),findsOneWidget);expect(offer.secondsRemaining(1000),29);await tester.ensureVisible(find.byKey(const ValueKey('decline_ride')));await tester.tap(find.byKey(const ValueKey('decline_ride')));expect(action,'decline');});}
